package com.example.mementowidgets;
import android.appwidget.AppWidgetManager;import android.appwidget.AppWidgetProvider;import android.content.ComponentName;import android.content.Context;import android.content.Intent;import android.app.PendingIntent;import android.widget.RemoteViews;import java.time.LocalDate;import java.time.temporal.ChronoUnit;import java.util.Locale;
public class LifeWidget extends AppWidgetProvider {
 public static void refresh(Context c){AppWidgetManager m=AppWidgetManager.getInstance(c);int[] ids=m.getAppWidgetIds(new ComponentName(c,LifeWidget.class));for(int id:ids)update(c,m,id);}
 static void update(Context c,AppWidgetManager m,int id){LocalDate birth=Store.dob(c),today=LocalDate.now();int years=Store.lifespan(c);long lived=Math.max(0,ChronoUnit.DAYS.between(birth,today));long total=Math.max(1,ChronoUnit.DAYS.between(birth,birth.plusYears(years)));double percent=100.0*lived/total;RemoteViews v=new RemoteViews(c.getPackageName(),R.layout.life_widget);v.setTextViewText(R.id.life_percent,String.format(Locale.US,"%.2f%%",percent));v.setProgressBar(R.id.life_bar,10000,(int)Math.min(10000,Math.round(percent*100)),false);v.setTextViewText(R.id.life_lived,String.format(Locale.US,"%.1f years lived",lived/365.2425));v.setTextViewText(R.id.life_remaining,String.format(Locale.US,"%.1f years left*",Math.max(0,total-lived)/365.2425));Intent open=new Intent(c,MainActivity.class);v.setOnClickPendingIntent(R.id.life_title,PendingIntent.getActivity(c,10,open,PendingIntent.FLAG_UPDATE_CURRENT|PendingIntent.FLAG_IMMUTABLE));m.updateAppWidget(id,v);}
 @Override public void onUpdate(Context c,AppWidgetManager m,int[] ids){for(int id:ids)update(c,m,id);}
}
